--로그체스 소환 시 특정 버프 부여
local local_class = newclass('RogueChessElementalAdvAtkOption')

--- init stage option
function local_class:init(option, c, slot, param)
	--- 옵션
	self.option = option

	--- 옵션의 오너
	self.owner = c

	self.level = self.option.Level

	local atk_modifier_base = CS.Utils.GetFloatFromDictionary(param, "DamageBoostBase");
	local atk_modifier_add = CS.Utils.GetFloatFromDictionary(param, "DamageBoostAdd");
	local owner_type = self.owner.CharacterStatsBehaviour.CharacterSpec.ElementalType;

	local default_type = CS.Oak.ElementalTypeExtensions.GetWeakness(owner_type);
	self.target_type = CS.Utils.GetElementalTypeFromDictionary(param, "TargetElementalType", default_type);
	self.attack_modifier = atk_modifier_base + atk_modifier_add * option.Level;
end

function local_class:get_attack_modifier(target, info)
	if target.CharacterStatsBehaviour and target.CharacterStatsBehaviour.CharacterSpec.ElementalType ~= self.target_type then
		return 1;
	end
	return 1 + self.attack_modifier;
end

function local_class:is_loaded()
	return true
end

--- dispose option
function local_class:dispose()
	self.target_type = nil
	self.option = nil
	self.owner = nil
end


return {
	create = function(option, c, slot, param)
		return local_class(option, c, slot, param)
	end,
}

